import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import axios from 'axios';
import toast from 'react-hot-toast';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import './UserDashboard.css';

const UserDashboard = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [leads, setLeads] = useState([]);
  const [savedLeads, setSavedLeads] = useState([]);
  const [loading, setLoading] = useState(true);
  const [scraping, setScraping] = useState(false);
  const [scraperResults, setScraperResults] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isDarkMode, setIsDarkMode] = useState(true);

  // === NEW: Lead Detail Modal State ===
  const [selectedLead, setSelectedLead] = useState(null);

  const [scraperData, setScraperData] = useState({
    city: 'Lahore',
    country: 'Pakistan',
    businessType: 'IT Company',
    maxResults: 10
  });

  const { user, logout, token } = useAuth();
  const navigate = useNavigate();

  const [stats, setStats] = useState({
    totalLeads: 0,
    savedLeads: 0,
    cities: 0,
    emails: 0
  });

  useEffect(() => {
    fetchLeads();
  }, []);

  const fetchLeads = async () => {
    try {
      const response = await axios.get('/leads', {
        headers: { Authorization: `Bearer ${token}` }
      });
      const data = response.data.data || [];
      setLeads(data);
      setSavedLeads(data.filter(l => l.isSaved));

      const cities = [...new Set(data.map(l => l.city).filter(Boolean))];
      const emails = data.filter(l => l.email).length;

      setStats({
        totalLeads: data.length,
        savedLeads: savedLeads.length,
        cities: cities.length,
        emails: emails
      });
    } catch (error) {
      toast.error('Failed to load leads');
    } finally {
      setLoading(false);
    }
  };

  const handleScraperChange = (e) => {
    setScraperData({ ...scraperData, [e.target.name]: e.target.value });
  };

  const quickNiche = (niche) => {
    setScraperData({ ...scraperData, businessType: niche });
  };

  // ===================================================
  // RUN SCRAPER & AUTO SAVE ALL LEADS
  // ===================================================
  const runScraper = async () => {
    const { city, country, businessType, maxResults } = scraperData;

    if (!city || !businessType) {
      toast.error('City and Business Type are required');
      return;
    }

    setScraping(true);
    setScraperResults([]);
    toast.loading('🌐 Scraping Google Maps...');

    try {
      const response = await axios.post('/scraper/run', {
        city,
        country,
        businessType,
        maxResults: parseInt(maxResults)
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success) {
        toast.dismiss();
        toast.success(`✅ Found ${response.data.count} leads!`);
        setScraperResults(response.data.leads || []);

        // === AUTO SAVE ALL SCRAPED LEADS TO MY LEADS ===
        if (response.data.leads && response.data.leads.length > 0) {
          toast.loading(`💾 Auto-saving ${response.data.leads.length} leads...`);
          try {
            // Is lead ka save karne ka backend route call karein
            for (let lead of response.data.leads) {
              await axios.post('/leads', lead, {
                headers: { Authorization: `Bearer ${token}` }
              });
            }
            toast.dismiss();
            toast.success(`✅ All ${response.data.leads.length} leads saved to "My Leads"!`);
            fetchLeads(); // Refresh My Leads list
          } catch (saveError) {
            toast.dismiss();
            toast.error('Failed to auto-save some leads.');
          }
        }

        setActiveTab('leads');
      } else {
        toast.dismiss();
        toast.error(response.data.message || 'Scraper failed');
      }
    } catch (error) {
      toast.dismiss();
      console.error('Scraper Error:', error);
      toast.error(error.response?.data?.message || 'Failed to scrape. Check backend.');
    } finally {
      setScraping(false);
    }
  };

  // ===================================================
  // SAVE SINGLE LEAD FUNCTION
  // ===================================================
  const handleSaveLead = async (leadId) => {
    try {
      await axios.put(`/leads/${leadId}/save`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      toast.success('⭐ Lead saved!');
      fetchLeads();
    } catch (error) {
      toast.error('Failed to save');
    }
  };

  // ===================================================
  // BULK SAVE FUNCTION (Select and save all unsaved)
  // ===================================================
  const handleBulkSave = async () => {
    const unsavedLeads = leads.filter(l => !l.isSaved);
    if (unsavedLeads.length === 0) {
      toast.error('All leads are already saved!');
      return;
    }

    toast.loading(`💾 Saving ${unsavedLeads.length} leads...`);
    try {
      for (let lead of unsavedLeads) {
        await handleSaveLead(lead._id);
      }
      toast.dismiss();
      toast.success(`✅ All ${unsavedLeads.length} leads saved successfully!`);
      fetchLeads();
    } catch (error) {
      toast.dismiss();
      toast.error('Failed to bulk save leads.');
    }
  };

  const handleUnsaveLead = async (leadId) => {
    try {
      await axios.put(`/leads/${leadId}/unsave`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      toast.success('Lead unsaved');
      fetchLeads();
    } catch (error) {
      toast.error('Failed to unsave');
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/login');
    toast.success('Logged out');
  };

  const toggleTheme = () => {
    setIsDarkMode(!isDarkMode);
    document.body.classList.toggle('light-theme');
  };

  const filteredLeads = leads.filter(lead =>
    lead.companyName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    lead.industry?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    lead.city?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const exportCSV = () => {
    if (leads.length === 0) {
      toast.error('No leads to export');
      return;
    }

    const headers = ['Company', 'Email', 'Phone', 'Website', 'Industry', 'City', 'Country', 'Rating', 'Status'];
    const rows = leads.map(l => [
      l.companyName || '',
      l.email || '',
      l.phone || '',
      l.website || '',
      l.industry || '',
      l.city || '',
      l.country || '',
      l.rating || '',
      l.status || 'New'
    ]);

    const csv = [headers, ...rows].map(r => r.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'leads_export.csv';
    a.click();
    toast.success(`📊 Exported ${leads.length} leads!`);
  };

  if (loading) return (
    <div className="loading-container">
      <div className="loader"></div>
      <p>Loading your dashboard...</p>
    </div>
  );

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: 'fa-solid fa-gauge-high' },
    { id: 'scraper', label: 'Lead Scraper', icon: 'fa-solid fa-magnifying-glass-location' },
    { id: 'leads', label: 'My Leads', icon: 'fa-solid fa-users' },
    { id: 'analytics', label: 'Analytics', icon: 'fa-solid fa-chart-line' },
    { id: 'settings', label: 'Settings', icon: 'fa-solid fa-sliders' }
  ];

  // ===================================================
  // LEAD DETAIL MODAL (Popup)
  // ===================================================
  const LeadDetailModal = ({ lead, onClose }) => {
    if (!lead) return null;
    return (
      <div className="modal-overlay" onClick={onClose}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={onClose}>×</button>
          <h2 className="modal-title"><i className="fa-solid fa-building"></i> {lead.companyName}</h2>
          <div className="modal-body">
            <div className="modal-row"><strong>Industry:</strong> {lead.industry || 'N/A'}</div>
            <div className="modal-row"><strong>Email:</strong> {lead.email || 'N/A'}</div>
            <div className="modal-row"><strong>Phone:</strong> {lead.phone || 'N/A'}</div>
            <div className="modal-row"><strong>Website:</strong> {lead.website ? <a href={lead.website} target="_blank" rel="noopener noreferrer">{lead.website}</a> : 'N/A'}</div>
            <div className="modal-row"><strong>Address:</strong> {lead.address || 'N/A'}</div>
            <div className="modal-row"><strong>City/Country:</strong> {lead.city || 'N/A'}, {lead.country || 'N/A'}</div>
            <div className="modal-row"><strong>Status:</strong> <span className={`status-badge ${lead.status}`}>{lead.status}</span></div>
          </div>
          <div className="modal-actions">
            {lead.isSaved ? (
              <button onClick={() => handleUnsaveLead(lead._id)} className="unsave-btn">Unsave</button>
            ) : (
              <button onClick={() => handleSaveLead(lead._id)} className="save-btn">Save Lead</button>
            )}
            <button onClick={onClose} className="close-btn">Close</button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className={`user-dashboard ${isDarkMode ? 'dark' : 'light'}`}>
      {/* Show Modal when a lead is clicked */}
      {selectedLead && <LeadDetailModal lead={selectedLead} onClose={() => setSelectedLead(null)} />}

      <aside className="sidebar">
        {/* ... Sidebar Code (Same as before) ... */}
        <div className="sidebar-brand">
          <div className="brand-icon"><i className="fa-solid fa-crosshairs"></i></div>
          <div className="brand-text"><h2>LeadHunter</h2><span>Pro</span></div>
        </div>
        <nav className="sidebar-nav">
          {navItems.map(item => (
            <button key={item.id} className={`nav-item ${activeTab === item.id ? 'active' : ''}`} onClick={() => setActiveTab(item.id)}>
              <i className={item.icon}></i><span>{item.label}</span>
              {item.id === 'leads' && <span className="badge">{savedLeads.length}</span>}
            </button>
          ))}
        </nav>
        <div className="sidebar-footer">
          <div className="user-info">
            <div className="avatar">{user?.name?.charAt(0) || 'U'}</div>
            <div className="user-details"><p className="name">{user?.name || 'User'}</p><p className="role">{user?.role || 'User'}</p></div>
          </div>
          <button onClick={handleLogout} className="logout-btn"><i className="fa-solid fa-power-off"></i></button>
        </div>
      </aside>

      <main className="main-content">
        <header className="main-header">
          <div className="header-left">
            <h1>{navItems.find(item => item.id === activeTab)?.label || 'Dashboard'}</h1>
            <p className="subtitle">
              {activeTab === 'dashboard' && `Welcome back, ${user?.name}!`}
              {activeTab === 'scraper' && '🌍 Find business leads from any country on Google Maps'}
              {activeTab === 'leads' && `📋 You have ${savedLeads.length} saved leads`}
              {activeTab === 'analytics' && '📊 Your lead generation insights'}
              {activeTab === 'settings' && '⚙️ Manage your account settings'}
            </p>
          </div>
          <div className="header-right">
            <button onClick={toggleTheme} className="theme-btn"><i className={`fa-solid ${isDarkMode ? 'fa-moon' : 'fa-sun'}`}></i></button>
            {activeTab === 'leads' && leads.length > 0 && (
              <button onClick={exportCSV} className="export-btn"><i className="fa-solid fa-file-export"></i> Export CSV</button>
            )}
          </div>
        </header>

        {/* ... Dashboard, Scraper, Analytics, Settings tabs remain the same as your existing code ... */}
        {/* I am showing the updated LEADS tab below since that is what you asked to change */}

        {/* ===========================================
            TAB: LEADS (With Click to Open Detail)
           =========================================== */}
        {activeTab === 'leads' && (
          <div className="tab-content leads-tab">
            <div className="leads-header">
              <div className="leads-search">
                <i className="fa-solid fa-search"></i>
                <input type="text" placeholder="Search leads by name, industry, or city..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
              </div>
              <div className="leads-actions">
                <span className="leads-count">{savedLeads.length} Saved</span>
                <button onClick={handleBulkSave} className="bulk-save-btn"><i className="fa-solid fa-check-double"></i> Save All</button>
              </div>
            </div>

            <div className="leads-grid">
              {filteredLeads.length === 0 ? (
                <div className="empty-state">
                  <i className="fa-solid fa-inbox"></i>
                  <p>No leads found</p>
                  <button onClick={() => setActiveTab('scraper')} className="primary-btn">Go to Scraper</button>
                </div>
              ) : (
                filteredLeads.map(lead => (
                  <div key={lead._id} className="lead-card clickable" onClick={() => setSelectedLead(lead)}>
                    <div className="lead-card-header">
                      <h3>{lead.companyName}{lead.rating && <span className="rating-badge">⭐ {lead.rating}</span>}</h3>
                      <span className={`status-badge ${lead.status}`}>{lead.status}</span>
                    </div>
                    <div className="lead-card-body">
                      {lead.industry && <p><i className="fa-solid fa-tag"></i> {lead.industry}</p>}
                      {lead.city && <p><i className="fa-solid fa-city"></i> {lead.city}{lead.country ? `, ${lead.country}` : ''}</p>}
                      {lead.phone && <p><i className="fa-solid fa-phone"></i> {lead.phone}</p>}
                      {lead.email && <p><i className="fa-solid fa-envelope"></i> {lead.email}</p>}
                    </div>
                    <div className="lead-card-actions">
                      {lead.isSaved ? (
                        <button onClick={(e) => { e.stopPropagation(); handleUnsaveLead(lead._id); }} className="unsave-btn"><i className="fa-solid fa-bookmark"></i> Saved</button>
                      ) : (
                        <button onClick={(e) => { e.stopPropagation(); handleSaveLead(lead._id); }} className="save-btn"><i className="fa-regular fa-bookmark"></i> Save</button>
                      )}
                      <span className="click-hint"><i className="fa-solid fa-arrow-up-right-from-square"></i> Click to view</span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default UserDashboard;
